reindexLatestChat() {
  const browserId = this.selectedSession?.id
  if (!browserId) return
  const chats = this.linkedChatIds
    .map(id => this.chatMetaById(id))
    .filter(Boolean)
  this.$storex.chats.rememberLatestBrowserChat({ browserId, chats })
