<script>
import CoworkingVolumeExplorer from './CoworkingVolumeExplorer.vue'

/**
 * Read-only view of the volume mappings shared by a co-desktop container.
 *
 * Two sources, in this order:
 *
 *  1. `session.mounts` — when the backend reports the binds it actually
 *     created (docker inspect). That is the truth, so it wins.
 *  2. The session settings (`share_project` / `share_folders` / `readonly` /
 *     `downloads_folder`) resolved with the SAME rule the new-session dialog
 *     applies (`/home/<project_name>` and `/shared` for VMs), so the settings
 *     panel explains what the container sees even for older sessions.
 */
export default {
  name: 'CoworkingVolumeMappings',
  components: { CoworkingVolumeExplorer },
  props: {
    session: { type: Object, default: null }
  },
  data() {
    return {
      // Volume opened in the file explorer (`{ path, title, containerPath }`),
      // null while the explorer is closed.
      explorer: null
    }
  },
  computed: {
    /** Absolute path of the project: the base every bind is resolved against. */
    absoluteProjectPath() {
      const root = this.$project?.abs_project_path ||
        this.$storex?.projects?.activeProject?.abs_project_path ||
        ''
      return String(root).replace(/\/+$/, '')
    },
    kind() {
      return this.session?.kind || 'browser'
    },
    /** Docker container name (the id as a fallback): what infra searches by. */
    containerName() {
      return this.session?.container_name ||
        this.session?.containerName ||
        this.session?.docker?.name ||
        this.session?.container_id ||
        ''
    },
    isRemote() {
      return this.kind === 'remote'
    },
    isVm() {
      return this.kind === 'windows' || this.kind === 'macos'
    },
    readonly() {
      return !!this.session?.readonly
    },
    projectName() {
      return this.$project?.project_name ||
        this.$storex?.projects?.activeProject?.project_name ||
        'project'
    },
    /** Mirror of the backend rule that builds `/home/<project_name>`. */
    projectFolderName() {
      const name = String(this.projectName || '')
        .replace(/[^A-Za-z0-9._-]+/g, '-')
        .replace(/^[-._]+|[-._]+$/g, '')
      return name || 'project'
    },
    homePath() {
      return `/home/${this.projectFolderName}`
    },
    /** Normalized container -> project mappings. */
    mappings() {
      if (!this.session) return []
      const reported = this.reportedMounts()
      if (reported.length) return reported
      if (this.isRemote) return []

      if (this.isVm) {
        const relative = this.normalizeFolder(this.session.downloads_folder)
        return [{
          container: this.kind === 'windows' ? 'Z:\\' : '/shared',
          project: relative ? `/${relative}` : '/ (whole project)',
          readonly: false
        }]
      }

      const folders = (this.session.share_folders || [])
        .map(folder => this.normalizeFolder(folder))
        .filter(Boolean)

      const list = []
      if (this.session.share_project) {
        list.push({ container: this.homePath, project: '/ (whole project)', readonly: this.readonly })
      } else {
        folders.forEach(folder => {
          list.push({
            container: `${this.homePath}/${folder}`,
            project: `/${folder}`,
            readonly: this.readonly
          })
        })
      }

      // A read-only session sends the downloads to their own bind.
      const downloads = this.normalizeFolder(this.session.downloads_folder)
      if (this.readonly && downloads) {
        list.push({ container: '/downloads', project: `/${downloads}`, readonly: false })
      }
      return list
    },
    emptyHint() {
      if (this.isRemote) return 'This co-desktop runs on a remote machine: it keeps its own filesystem.'
      return 'No project folder is mounted: the session cannot read or write project files.'
    },
    /** Why a volume cannot be browsed (used as the row tooltip). */
    exploreHint() {
      if (this.isRemote) return 'A remote machine keeps its own filesystem'
      return 'This bind has no project folder behind it'
    }
  },
  methods: {
    /**
     * Project-relative path behind a bind, or null when it cannot be browsed.
     *
     * The files API speaks project-relative paths (`''` is the project root),
     * while a bind speaks container paths and a docker inspect speaks host
     * paths. All three are folded into the one the explorer understands.
     */
    volumePath(mapping) {
      if (!mapping || this.isRemote) return null
      const raw = String(mapping.project || '').trim()
      if (!raw || raw === '—') return null
      const base = this.absoluteProjectPath
      // A bind reported by docker inspect is a host path inside the project.
      if (base && (raw === base || raw.startsWith(`${base}/`))) {
        return raw.slice(base.length).replace(/^\/+/, '')
      }
      // `/ (whole project)` is the label of the root bind.
      if (raw === '/' || raw.startsWith('/ ')) return ''
      const home = this.homePath
      if (raw === home) return ''
      if (raw.startsWith(`${home}/`)) return raw.slice(home.length + 1)
      if (this.isVm && raw.startsWith('/shared')) {
        return raw.slice('/shared'.length).replace(/^\/+/, '')
      }
      return raw.replace(/^\/+/, '')
    },
    isExplorable(mapping) {
      return this.volumePath(mapping) !== null
    },
    /** Open a volume in the file explorer modal. */
    openExplorer(mapping) {
      const path = this.volumePath(mapping)
      if (path === null) return
      this.explorer = {
        path,
        title: path ? `/${path}` : 'Whole project files',
        containerPath: mapping.container,
        readonly: !!mapping.readonly
      }
    },
    /**
     * Jump to the infrastructure view with this container selected.
     *
     * `InfraView` opens the detail drawer from the `container` query param, so
     * the operator lands on the right container instead of searching the list.
     */
    openInInfra() {
      const id = this.containerName
      if (!id) return
      const projectName = this.$route?.params?.projectName
      const path = projectName ? `/${projectName}/infra` : '/infra'
      this.$router.push({ path, query: { container: id } })
    },

    /** Accepts the shapes a backend may use for a bind. */
    reportedMounts() {
      const raw = this.session?.mounts || this.session?.volume_mappings || this.session?.binds
      if (!Array.isArray(raw)) return []
      return raw
        .map(entry => {
          if (typeof entry === 'string') {
            // "host:container[:mode]"
            const parts = entry.split(':')
            if (parts.length < 2) return null
            return {
              project: parts[0],
              container: parts[1],
              readonly: (parts[2] || '').split(',').includes('ro')
            }
          }
          if (!entry || typeof entry !== 'object') return null
          const container = entry.container || entry.target || entry.destination || entry.mount
          const project = entry.project || entry.source || entry.host || entry.origin
          if (!container) return null
          return {
            container,
            project: project || '—',
            readonly: entry.readonly ?? entry.read_only ?? entry.ro ?? (entry.mode || '').includes('ro')
          }
        })
        .filter(Boolean)
    },
    normalizeFolder(value) {
      return String(value || '')
        .replace(/\\/g, '/')
        .replace(/\/{2,}/g, '/')
        .replace(/^\/+|\/+$/g, '')
    }
  }
}
</script>

