  },
  methods: {
    resetForSession() {
      this.stopPolling()
      this.vncPath = null
      this.vncPassword = ''
      this.viewerUser = ''
      this.viewerPassword = ''
      this.vncTicketError = null
      this.pollFallback = false
      this.screenshot = null
      this.screenshotData = null
      this.error = null
