/**
 * Volume mapping rules shared by the coworking session UI.
 *
 * A co-desktop container sees the project through bind mounts. Two sources, in
 * this order:
 *
 *  1. `session.mounts` — the binds the backend actually created (docker
 *     inspect). That is the truth, so it wins.
 *  2. the session settings (`share_project` / `share_folders` / `readonly` /
 *     `downloads_folder`), resolved with the SAME rule the new-session dialog
 *     applies (`/home/<project_name>` and `/shared` for VMs), so the UI can
 *     explain what the container sees even for older sessions.
 *
 * Keeping the rules here (instead of inside one component) means the settings
 * table and the folder browser below the viewer cannot disagree about which
 * project folder a bind points at.
 */

/** Project-relative folder, without leading/trailing slash. */
export function normalizeFolder(value) {
  return String(value || '')
    .replace(/\\/g, '/')
    .replace(/\/{2,}/g, '/')
    .replace(/^\/+|\/+$/g, '')
}

/** Mirror of the backend rule that builds `/home/<project_name>`. */
export function projectFolderName(projectName) {
  const name = String(projectName || '')
    .replace(/[^A-Za-z0-9._-]+/g, '-')
    .replace(/^[-._]+|[-._]+$/g, '')
  return name || 'project'
}

export function isRemoteSession(session) {
  return (session?.kind || 'browser') === 'remote'
}

export function isVmSession(session) {
  const kind = session?.kind
  return kind === 'windows' || kind === 'macos'
}

/** Accepts the shapes a backend may use for a bind. */
export function reportedMounts(session) {
  const raw = session?.mounts || session?.volume_mappings || session?.binds
  if (!Array.isArray(raw)) return []
  return raw
    .map((entry) => {
      if (typeof entry === 'string') {
        // "host:container[:mode]"
        const parts = entry.split(':')
        if (parts.length < 2) return null
        return {
          project: parts[0],
          container: parts[1],
          readonly: (parts[2] || '').split(',').includes('ro')
        }
      }
      if (!entry || typeof entry !== 'object') return null
      const container = entry.container || entry.target || entry.destination || entry.mount
      const project = entry.project || entry.source || entry.host || entry.origin
      if (!container) return null
      return {
        container,
        project: project || '—',
        readonly: entry.readonly ?? entry.read_only ?? entry.ro ?? (entry.mode || '').includes('ro')
      }
    })
    .filter(Boolean)
}

/**
 * Normalized `{ container, project, readonly }` list for a session.
 */
export function resolveVolumeMappings(session, { projectName = '' } = {}) {
  if (!session) return []
  const reported = reportedMounts(session)
  if (reported.length) return reported
  if (isRemoteSession(session)) return []

  const home = `/home/${projectFolderName(projectName)}`
  const readonly = !!session.readonly

  if (isVmSession(session)) {
    const relative = normalizeFolder(session.downloads_folder)
    return [{
      container: session.kind === 'windows' ? 'Z:\\' : '/shared',
      project: relative ? `/${relative}` : '/ (whole project)',
      readonly: false
    }]
  }

  const folders = (session.share_folders || [])
    .map(folder => normalizeFolder(folder))
    .filter(Boolean)

  const list = []
  if (session.share_project) {
    list.push({ container: home, project: '/ (whole project)', readonly })
  } else {
    folders.forEach(folder => {
      list.push({
        container: `${home}/${folder}`,
        project: `/${folder}`,
        readonly
      })
    })
  }

  // A read-only session sends the downloads to their own bind.
  const downloads = normalizeFolder(session.downloads_folder)
  if (readonly && downloads) {
    list.push({ container: '/downloads', project: `/${downloads}`, readonly: false })
  }
  return list
}

/**
 * Project-relative path behind a bind, or null when it cannot be browsed.
 *
 * The files API speaks project-relative paths (`''` is the project root), while
 * a bind speaks container paths and a docker inspect speaks host paths. All
 * three are folded into the one the file browser understands.
 */
export function volumePath(mapping, session, { projectName = '', absoluteProjectPath = '' } = {}) {
  if (!mapping || isRemoteSession(session)) return null
  const raw = String(mapping.project || '').trim()
  if (!raw || raw === '—') return null
  const base = String(absoluteProjectPath || '').replace(/\/+$/, '')
  // A bind reported by docker inspect is a host path inside the project.
  if (base && (raw === base || raw.startsWith(`${base}/`))) {
    return raw.slice(base.length).replace(/^\/+/, '')
  }
  // `/ (whole project)` is the label of the root bind.
  if (raw === '/' || raw.startsWith('/ ')) return ''
  const home = `/home/${projectFolderName(projectName)}`
  if (raw === home) return ''
  if (raw.startsWith(`${home}/`)) return raw.slice(home.length + 1)
  if (isVmSession(session) && raw.startsWith('/shared')) {
    return raw.slice('/shared'.length).replace(/^\/+/, '')
  }
  return raw.replace(/^\/+/, '')
}

/**
 * The browsable volumes of a session, ready for the file browser:
 * `[{ path, label, containerPath, readonly }]`.
 */
export function explorableVolumeRoots(session, options = {}) {
  return resolveVolumeMappings(session, options)
    .map((mapping) => {
      const path = volumePath(mapping, session, options)
      if (path === null) return null
      return {
        path,
        label: path ? `/${path}` : 'Whole project',
        containerPath: mapping.container,
        readonly: !!mapping.readonly
      }
    })
    .filter(Boolean)
}

