              :session="selectedSession"
              :meet-id="meetId"
              @ask-ai="onAskAiAboutPage"
              @send-annotations="onSendAnnotations"
              @share-session="onShareSession"
            />
            <DesktopViewer
              v-else
              :session="selectedSession"
              @ask-ai="onAskAiAboutPage"
            />
          </div>
        </template>

